import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// In-process fake of the downstream pricing service (unit price in euros).
const prices = { A: 10, B: 25, C: 101, D: 100, E: 0.5 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})

test('POST /orders -> 201 with id, echoed items and summed total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.match(body.id, /^\d+$/)
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }])
  assert.equal(body.total, 45)
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
})

test('POST /orders ids increment by one', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders asks pricing once per item line, in order', async () => {
  calls.length = 0
  await post({ items: [{ sku: 'B', qty: 1 }, { sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }] })
  assert.deepEqual(calls, ['B', 'A', 'B'])
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  assert.equal((await (await post({ items: [{ sku: 'D', qty: 1 }] })).json()).total, 100)
})

test('POST /orders: total over 100 gets 10% off, floored', async () => {
  // 101 - 10.1 = 90.9 -> 90
  assert.equal((await (await post({ items: [{ sku: 'C', qty: 1 }] })).json()).total, 90)
  assert.equal((await (await post({ items: [{ sku: 'B', qty: 8 }] })).json()).total, 180)
})

test('POST /orders: fractional total is floored', async () => {
  assert.equal((await (await post({ items: [{ sku: 'E', qty: 3 }] })).json()).total, 1)
})

test('POST /orders: missing qty serialises total as null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty undefined gives NaN, JSON renders null, still 201.
  const res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders: unknown sku serialises total as null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — fake pricing returns undefined for unknown sku -> NaN -> null, 201.
  const res = await post({ items: [{ sku: 'ZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

for (const [name, body, raw] of [
  ['empty body', undefined, ''],
  ['empty object', {}],
  ['items not an array', { items: 'x' }],
  ['empty items', { items: [] }],
  ['invalid JSON', undefined, '{nope'],
]) {
  test(`POST /orders -> 400 for ${name}`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id unknown id -> 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404.
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('GET /orders/:id ignores the query string', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.deepEqual(await (await fetch(`${base}/orders/${created.id}?x=1`)).json(), created)
})

for (const [method, path] of [
  ['GET', '/orders'], ['GET', '/orders/'], ['GET', '/nope'], ['DELETE', '/orders/1'],
  ['PUT', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/items'],
]) {
  test(`${method} ${path} -> 404 no route`, async () => {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'no route' })
  })
}
EOF
